// 恢复可写后重新提交才生效，且只记录从最后成功保存的日期出发的一条改期。
func TestFailedRescheduleSaveLeavesNoChange(t *testing.T) {
	clock := &fakeClock{t: mustDate(t, "2026-10-02")}
	path := filepath.Join(t.TempDir(), "ledger.json")
