// 文件不可写时，计划不存在、已结束或取消原因为空白仍按既有方式拒绝（校验错误
// 或 ErrNotFound），且不进行写盘尝试、不改动任何已有记录。
func TestCancelValidationRejectedWhileSavingBlocked(t *testing.T) {
