	mustPlan(t, l, PlanInput{Number: "P-2", InstrumentID: "M-1", Date: "2026-10-11", Note: "备用"})
	// 先成功取消 P-2，构造一项已结束计划。
	if _, err := l.CancelPlan("P-2", "不再需要"); err != nil {
