	}
	raw, err = os.ReadFile(target)
	if err != nil {
		t.Fatalf("读取台账文件: %v", err)
	}
	if strings.Contains(string(raw), "暂停送检") {
		t.Fatalf("失败申请的原因最终仍被写入文件：\n%s", raw)
	}
}

